def get_weather(city: str) -> str:
    return f"{city}: 18C, light rain"

TOOLS = {"get_weather": get_weather}
# the model outputs: {"tool": "get_weather", "args": {"city": "Paris"}}
observation = TOOLS["get_weather"](city="Paris")

history.append({
    "role": "tool",
    "tool_call_id": call.id,
    "content": observation,   # e.g. 'Paris: 18C, light rain'
})
# next llm() call now 'knows' the weather
